#!/usr/bin/env python3
"""news-image-20261119 entry (variant 3: bold magazine cover).

Writes the finished 1024x1024 magazine cover summing up the world's
news of Thursday 19 November 2026 ("The Daily Globe", dominant Vice City
sunset scene for the GTA VI global rollout, plus the rest of the day's
stories) to /output/entry.png. The image is embedded below as one base64
line, so the program needs no network and no other files: it decodes the
bytes and writes them unchanged, so two runs produce byte-identical output.

Run:  MAKEFUN_OUTPUT_DIR=out python3 main.py
"""
import base64
import os

IMAGE_B64 = ""


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(IMAGE_B64)
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(data)


if __name__ == "__main__":
    main()
